ni-dedicated{min-width:68px;padding:7px 12px;border-radius:5px;font-weight:700;cursor:pointer}.mini-dedicated:disabled,.mini-save-quantity:disabled{opacity:.6;cursor:wait}.mini-yes{border:1px solid #3e9a62;background:#194d31;color:#b9f3cc}.mini-no{border:1px solid #65747c;background:#273740;color:#d7e0e4}.mini-quantity{width:88px;min-height:36px;padding:5px 8px;border:1px solid #607987;border-radius:5px;background:#edf2f5;color:#17242c;font-size:16px}.mini-save-quantity{margin-left:6px;padding:7px 9px;border:1px solid #2999a5;border-radius:4px;background:#174454;color:#fff;cursor:pointer}.mini-save-quantity.mini-saved{border-color:#3e9a62;background:#194d31}.mini-no-account{padding:24px;border:1px solid #6e5c31;border-radius:8px;background:#302817;text-align:center;color:#f3e3bd}.mini-account-name{color:#fff27a;font-weight:700}.mini-ajax-message{display:none;margin:0 auto 18px;max-width:620px;padding:10px 14px;border-radius:6px;text-align:center}.mini-ajax-message.is-error{display:block;border:1px solid #8d5050;background:#3b2020;color:#ffd0d0}.tonic-rarity{font-size:12px;color:#a9c5d1;margin-left:8px}@media(max-width:650px){.mini-summary{grid-template-columns:1fr}.mini-table th,.mini-table td{padding:9px 8px}.mini-save-quantity{display:none}}
