<?php
if (isset($_SESSION['userid'])) {
    $userid=(int)$_SESSION['userid']; $accid=(int)($_SESSION['prefaccid']??0);
    echo '<section class="mini-page"><div class="mini-heading"><h1>Miniature Collection</h1>';
    if ($accid<=0) { echo '<p>Track Hall of Monuments dedication and how many copies you currently have.</p></div><div class="mini-no-account">Select a Guild Wars account from the Account menu above before tracking miniatures.</div></section>'; include_once('footer.php'); exit; }
    $account=$con->prepare('SELECT accemail FROM gwaccounts WHERE accid=? AND userid=? LIMIT 1'); $account->bind_param('ii',$accid,$userid); $account->execute(); $accountRow=$account->get_result()->fetch_assoc(); $account->close();
    if (!$accountRow) { echo '<p>Track Hall of Monuments dedication and how many copies you currently have.</p></div><div class="mini-no-account">The selected Guild Wars account could not be found.</div></section>'; include_once('footer.php'); exit; }
    echo '<p>Tracking miniatures for <span class="mini-account-name">'.h($accountRow['accemail']).'</span></p><p>Dedicated status and on-hand quantity are independent: a dedicated miniature can still have an on-hand quantity of zero.</p></div>';

    $summary=$con->prepare('SELECT COALESCE(SUM(dedicated),0),COALESCE(SUM(quantity),0) FROM gwminiature_inventory WHERE userid=? AND accid=?'); $summary->bind_param('ii',$userid,$accid); $summary->execute(); $summary->bind_result($dedicatedCount,$miniTotal); $summary->fetch(); $summary->close();
    $tonicTotal=0; $tonicTable=$con->query("SHOW TABLES LIKE 'gwtonics'"); $hasTonics=$tonicTable && $tonicTable->num_rows>0;
    if ($hasTonics) { $s=$con->prepare('SELECT COALESCE(SUM(quantity),0) FROM gwtonic_inventory WHERE userid=? AND accid=?'); $s->bind_param('ii',$userid,$accid); $s->execute(); $s->bind_result($tonicTotal); $s->fetch(); $s->close(); }
    echo '<div id="mini-ajax-message" class="mini-ajax-message" role="status" aria-live="polite"></div><div class="mini-summary"><div class="mini-summary-card"><strong id="mini-dedicated-count">'.(int)$dedicatedCount.'</strong><span>distinct miniatures marked dedicated</span></div><div class="mini-summary-card"><strong id="mini-quantity-total">'.(int)$miniTotal.'</strong><span>miniatures currently on hand</span></div><div class="mini-summary-card"><strong id="tonic-quantity-total">'.(int)$tonicTotal.'</strong><span>6th year tonics currently on hand</span></div></div>';

    $groups=$con->query('SELECT groupid,groupkey,groupname,group_note FROM gwminiature_groups ORDER BY display_order,groupname');
    $miniStmt=$con->prepare("SELECT m.miniid,m.mininame,m.rarity,m.wiki_url,COALESCE(i.dedicated,0) dedicated,COALESCE(i.quantity,0) quantity FROM gwminiature_group_members gm JOIN gwminiatures m ON m.miniid=gm.miniid LEFT JOIN gwminiature_inventory i ON i.miniid=m.miniid AND i.userid=? AND i.accid=? WHERE gm.groupid=? ORDER BY FIELD(m.rarity,'Green','Gold','Purple','White'),m.mininame");
    while ($group=$groups->fetch_assoc()) {
        if ($group['groupkey']==='year6' && $hasTonics) {
            $tonics=$con->prepare("SELECT t.tonicid,t.tonicname,t.rarity,t.wiki_url,COALESCE(i.quantity,0) quantity FROM gwtonics t LEFT JOIN gwtonic_inventory i ON i.tonicid=t.tonicid AND i.userid=? AND i.accid=? ORDER BY FIELD(t.rarity,'White','Purple','Gold','Green'),t.display_order,t.tonicname"); $tonics->bind_param('ii',$userid,$accid); $tonics->execute(); $r=$tonics->get_result();
            echo '<details class="mini-group"><summary>Year 6 <small>('.$r->num_rows.')</small></summary><p class="mini-group-note">Sixth-year Birthday Presents contain everlasting tonics instead of miniatures. Tonics have no Hall of Monuments dedication status, so only on-hand quantity is tracked here.</p><div class="mini-table-wrap"><table class="mini-table"><thead><tr><th>Everlasting tonic</th><th>Rarity</th><th>On Hand</th></tr></thead><tbody>';
            while($t=$r->fetch_assoc()){ echo '<tr data-tonicid="'.(int)$t['tonicid'].'"><td>'.h($t['tonicname']).'</td><td>'.h($t['rarity']).'</td><td><form class="mini-inline-form tonic-ajax-form" action="includes/update-tonic.php" method="post">'.csrf_input().'<input type="hidden" name="tonicid" value="'.(int)$t['tonicid'].'"><input class="mini-quantity" type="number" name="quantity" min="0" max="999999" step="1" inputmode="numeric" value="'.(int)$t['quantity'].'"><button class="mini-save-quantity" type="submit">Save</button></form></td></tr>'; }
            echo '</tbody></table></div></details>'; $tonics->close(); continue;
        }
        $groupid=(int)$group['groupid']; $miniStmt->bind_param('iii',$userid,$accid,$groupid); $miniStmt->execute(); $miniResult=$miniStmt->get_result();
        echo '<details class="mini-group"><summary>'.h($group['groupname']).' <small>('.$miniResult->num_rows.')</small></summary>'; if(!empty($group['group_note'])) echo '<p class="mini-group-note">'.h($group['group_note']).'</p>';
        if($miniResult->num_rows===0) echo '<p class="mini-group-note">No miniatures in this group.</p>'; else { echo '<div class="mini-table-wrap"><table class="mini-table"><thead><tr><th>Miniature</th><th>HoM Dedicated</th><th>On Hand</th></tr></thead><tbody>';
            while($mini=$miniResult->fetch_assoc()){ $dedicated=(int)$mini['dedicated']===1; $rarity=strtolower((string)$mini['rarity']); $rarityClass=in_array($rarity,['green','gold','purple','white'],true)?'mini-rarity-'.$rarity:'mini-rarity-white'; $miniName=h($mini['mininame']); $wikiUrl=trim((string)($mini['wiki_url']??'')); if($wikiUrl!=='' && filter_var($wikiUrl,FILTER_VALIDATE_URL) && strcasecmp((string)parse_url($wikiUrl,PHP_URL_SCHEME),'https')===0){$miniName='<a class="mini-wiki-link" href="'.h($wikiUrl).'" target="_blank" rel="noopener noreferrer">'.$miniName.'</a>';} echo '<tr data-miniid="'.(int)$mini['miniid'].'"><td class="'.$rarityClass.'">'.$miniName.'</td><td><form class="mini-inline-form mini-ajax-form" action="includes/update-miniature.php" method="post">'.csrf_input().'<input type="hidden" name="miniid" value="'.(int)$mini['miniid'].'"><input type="hidden" name="action" value="toggle_dedicated"><button class="mini-dedicated '.($dedicated?'mini-yes':'mini-no').'" type="submit">'.($dedicated?'Yes':'No').'</button></form></td><td><form class="mini-inline-form mini-ajax-form" action="includes/update-miniature.php" method="post">'.csrf_input().'<input type="hidden" name="miniid" value="'.(int)$mini['miniid'].'"><input type="hidden" name="action" value="set_quantity"><input class="mini-quantity" type="number" name="quantity" min="0" max="999999" step="1" inputmode="numeric" value="'.(int)$mini['quantity'].'"><button class="mini-save-quantity" type="submit">Save</button></form></td></tr>'; }
            echo '</tbody></table></div>'; } echo '</details>';
    }
    $miniStmt->close(); echo '</section>';
}
include_once('footer.php');
?>
<script>
(() => {
 const message=document.getElementById('mini-ajax-message'),dedicatedCount=document.getElementById('mini-dedicated-count'),quantityTotal=document.getElementById('mini-quantity-total'),tonicTotal=document.getElementById('tonic-quantity-total'); if(!message||!window.fetch)return;
 const error=t=>{message.textContent=t||'Unable to update collection.';message.classList.add('is-error')},clear=()=>{message.textContent='';message.classList.remove('is-error')};
 async function submit(form,kind){clear();const button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;try{const response=await fetch(form.getAttribute('action'),{method:'POST',body:new FormData(form),headers:{'Accept':'application/json'},credentials:'same-origin'});let data;try{data=await response.json()}catch(_){throw new Error('The server returned an unexpected response.')}if(!response.ok||!data.ok)throw new Error(data.message||'Unable to update collection.');
   if(kind==='mini'){dedicatedCount.textContent=data.dedicated_count;quantityTotal.textContent=data.quantity_total;document.querySelectorAll('tr[data-miniid="'+data.miniid+'"]').forEach(row=>{const b=row.querySelector('.mini-dedicated');if(b){b.textContent=data.dedicated?'Yes':'No';b.classList.toggle('mini-yes',!!data.dedicated);b.classList.toggle('mini-no',!data.dedicated)}const q=row.querySelector('.mini-quantity');if(q)q.value=data.quantity})}
   else {tonicTotal.textContent=data.tonic_total;document.querySelectorAll('tr[data-tonicid="'+data.tonicid+'"]').forEach(row=>{const q=row.querySelector('.mini-quantity');if(q)q.value=data.quantity})}
   if(button&&button.classList.contains('mini-save-quantity')){const old=button.textContent;button.textContent='Saved';button.classList.add('mini-saved');setTimeout(()=>{button.textContent=old;button.classList.remove('mini-saved')},900)}
 }catch(e){error(e.message)}finally{if(button)button.disabled=false}}
 document.querySelectorAll('.mini-ajax-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();submit(f,'mini')})); document.querySelectorAll('.tonic-ajax-form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();submit(f,'tonic')}));
})();
</script>
